/**
 * Golden fixture tests: replay real recorded Dinkster WS streams
 * (fixtures/events/dinkster-streams.json, generated by running the real Dinkster
 * engine + engine_event_to_wire at backend commit 230ab1a) through
 * DinksterNormalizer and hold it to the contract guards:
 *
 * - every execution event routes by job identity (jobId -> ExecutionRef),
 *   never "the active tab"; unroutable events are dropped, not guessed
 * - success/cached streams terminate with exactly ONE 'completed' even though
 *   the wire carries both run_finished and job_state completed
 * - node_skipped is a NORMAL state with root provenance (origin), and a skip
 *   cascade produces zero error events on bystanders
 * - a fail-policy absence fails the JOB with no node_failed event: the error
 *   carries the culprit node, which must still be marked
 * - progress normalizes to bounded per-node values, previews decode from
 *   self-describing binary frames (4-byte BE header length + JSON + blob)
 * - concurrent jobs interleaved on one socket never cross-route
 * - completed-job hydration (nodeStatesFromDinksterJob) reconstructs per-node
 *   state from a fetched job record for frozen views after reload
 */
import { readFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { asConnectionId, asPromptId, executionKey } from '../src/ids.js'
import { DinksterNormalizer, nodeStatesFromDinksterJob, type DinksterJobWire, type DinksterRawJson, type DinksterRawMessage } from '../src/events/dinkster.js'
import { isExecutionEvent, type NodeProgress, type NormalizedEvent } from '../src/events/contract.js'
import { compositorStateOf } from '../src/compositor.js'

interface RecordedMessage extends Record<string, unknown> {
  readonly type: string
  readonly _binary?: boolean
  readonly _blobBase64?: string
}

interface RecordedStream {
  readonly job: DinksterJobWire & Record<string, unknown>
  readonly messages: readonly RecordedMessage[]
}

const fixturePath = join(
  dirname(fileURLToPath(import.meta.url)),
  '../fixtures/events/dinkster-streams.json',
)
const fixture = JSON.parse(readFileSync(fixturePath, 'utf8')) as {
  streams: readonly RecordedStream[]
}
// Generator order: success, cached, skip-cascade, failure.
const [successStream, cachedStream, skipStream, failureStream] = fixture.streams as [
  RecordedStream,
  RecordedStream,
  RecordedStream,
  RecordedStream,
]

const CONN = asConnectionId('conn-test')
const keyOf = (jobId: string): string =>
  executionKey({ connection: CONN, prompt: asPromptId(jobId) })

/** Rebuild the exact wire frame the server would send for one message. */
function toWire(m: RecordedMessage): DinksterRawMessage {
  if (m._binary !== true) return m as DinksterRawJson
  const { _binary, _blobBase64, ...header } = m
  const headerBytes = new TextEncoder().encode(JSON.stringify(header))
  const blob = Uint8Array.from(atob(_blobBase64 ?? ''), (c) => c.charCodeAt(0))
  const frame = new Uint8Array(4 + headerBytes.length + blob.length)
  new DataView(frame.buffer).setUint32(0, headerBytes.length, false)
  frame.set(headerBytes, 4)
  frame.set(blob, 4 + headerBytes.length)
  return frame.buffer
}

function replay(messages: readonly RecordedMessage[]): NormalizedEvent[] {
  const normalizer = new DinksterNormalizer(CONN, () => 0)
  const out: NormalizedEvent[] = []
  for (const m of messages) out.push(...normalizer.normalize(toWire(m)))
  return out
}

const nodeEntries = (events: readonly NormalizedEvent[]): [string, NodeProgress][] =>
  events.flatMap((e) => (e.kind === 'nodeStates' ? Object.entries(e.nodes) : []))

