describe('dinkster stream replay: success', () => {
  const events = replay(successStream.messages)

  it('starts once and completes exactly once (run_finished + job_state dedupe)', () => {
    const normalizer = new DinksterNormalizer(CONN, () => 0)
    const terminalIndex = successStream.messages.findIndex((message) =>
      message.type === 'job_state' && message['state'] === 'completed')
    const beforeTerminal = successStream.messages.slice(0, terminalIndex)
      .flatMap((message) => normalizer.normalize(toWire(message)))
    expect(beforeTerminal.some((event) => event.kind === 'completed')).toBe(false)
    expect(normalizer.normalize(toWire(successStream.messages[terminalIndex]!)))
      .toEqual([expect.objectContaining({ kind: 'completed' })])
    expect(events.filter((e) => e.kind === 'started')).toHaveLength(1)
    expect(events.filter((e) => e.kind === 'completed')).toHaveLength(1)
    const last = [...events].reverse().find((e) => e.kind !== 'status')!
    expect(last.kind).toBe('completed')
  })

  it('walks each node through running -> done via per-node state maps', () => {
    const byNode = new Map<string, NodeProgress['state'][]>()
    for (const [id, p] of nodeEntries(events)) {
      byNode.set(id, [...(byNode.get(id) ?? []), p.state])
    }
    for (const id of ['m', 'a', 'p', 'r']) {
      const states = byNode.get(id)!
      expect(states[0]).toBe('running')
      expect(states[states.length - 1]).toBe('done')
    }
  })

  it('carries per-output summaries on node_finished, length exactly for lists', () => {
    // detail.outputs (backend commit ea9ab93): {outputId: {typeId, length?}}
    // for INTERMEDIATE nodes mid-run, not just job-result targets.
    const done = new Map(nodeEntries(events).filter(([, p]) => p.state === 'done'))
    expect(done.get('r')!.outputs).toEqual({ items: { typeId: 'list<INT>', length: 3 } })
    expect(done.get('a')!.outputs).toEqual({ out: { typeId: 'INT', value: 8 } })
    expect(done.get('a')!.outputs!['out']).not.toHaveProperty('length')
  })

  it('normalizes progress to bounded values with max', () => {
    const progress = nodeEntries(events).filter(([, p]) => p.value !== undefined)
    expect(progress.length).toBeGreaterThan(0)
    for (const [id, p] of progress) {
      expect(id).toBe('a')
      expect(p.state).toBe('running')
      expect(p.value!).toBeGreaterThanOrEqual(0)
      expect(p.value!).toBeLessThanOrEqual(1)
      expect(p.max).toBe(2)
    }
    // Final progress step reaches 1.
    expect(progress[progress.length - 1]![1].value).toBe(1)
  })

  it('decodes the preview from a self-describing binary frame', () => {
    const previews = events.filter((e) => e.kind === 'preview')
    expect(previews).toHaveLength(1)
    const preview = previews[0]!
    if (preview.kind !== 'preview') throw new Error('unreachable')
    expect(preview.runtimeNodeId).toBe('p')
    expect(preview.channel).toBe('image/jpeg')
    expect(preview.payload).toBeInstanceOf(ArrayBuffer)
    const original = successStream.messages.find((m) => m._binary === true)!
    const expected = Uint8Array.from(atob(original._blobBase64!), (c) => c.charCodeAt(0))
    expect(new Uint8Array(preview.payload as ArrayBuffer)).toEqual(expected)
  })
})

describe('preview frame-ring metadata', () => {
  const previewMsg = (data: Record<string, unknown>): RecordedMessage => ({
    type: 'node_event', runId: 'run-ring', jobId: 'job-ring', nodeId: 'sampler',
    event: 'preview', data: { mime: 'image/jpeg', ...data },
  })
  const only = (events: NormalizedEvent[]) => {
    expect(events).toHaveLength(1)
    return events[0]! as Extract<NormalizedEvent, { kind: 'preview' }>
  }

  it('carries stream, ring addressing, and fps through normalization', () => {
    const preview = only(replay([
      previewMsg({ stream: 'video', frameIndex: 3, frameCount: 21, fps: 16 }),
    ]))
    expect(preview).toMatchObject({
      kind: 'preview',
      execution: { connection: CONN, prompt: 'job-ring' },
      runtimeNodeId: 'sampler',
      channel: 'image/jpeg',
      stream: 'video',
      frameIndex: 3,
      frameCount: 21,
      fps: 16,
    })
  })

})

