describe('dinkster stream replay: cached', () => {
  const events = replay(cachedStream.messages)

  it('marks every node cached and completes once', () => {
    const cached = nodeEntries(events).filter(([, p]) => p.state === 'cached')
    expect(new Set(cached.map(([id]) => id))).toEqual(new Set(['m', 'a', 'p', 'r']))
    expect(events.filter((e) => e.kind === 'completed')).toHaveLength(1)
    expect(events.filter((e) => e.kind === 'error')).toHaveLength(0)
  })

  it('cache hits carry the same per-output summaries as fresh finishes', () => {
    const cached = new Map(nodeEntries(events).filter(([, p]) => p.state === 'cached'))
    expect(cached.get('r')!.outputs).toEqual({ items: { typeId: 'list<INT>', length: 3 } })
    expect(cached.get('a')!.outputs).toEqual({ out: { typeId: 'INT', value: 8 } })
  })
})

describe('dinkster stream replay: skip cascade', () => {
  const events = replay(skipStream.messages)

  it('normalizes node_skipped to a normal skipped state with root provenance', () => {
    const skipped = nodeEntries(events).filter(([, p]) => p.state === 'skipped')
    expect(new Set(skipped.map(([id]) => id))).toEqual(new Set(['a', 'b']))
    // Both bystanders point at the ONE root origin, never each other.
    for (const [, p] of skipped) expect(p.skipOrigin).toBe('m/value')
  })

  it('produces zero error events and still completes', () => {
    expect(events.filter((e) => e.kind === 'error')).toHaveLength(0)
    expect(nodeEntries(events).filter(([, p]) => p.state === 'error')).toHaveLength(0)
    expect(events.filter((e) => e.kind === 'completed')).toHaveLength(1)
  })
})

describe('dinkster stream replay: fail-policy failure (no node_failed event)', () => {
  const events = replay(failureStream.messages)

  it('terminates with an error carrying the culprit node and message', () => {
    expect(events.filter((e) => e.kind === 'completed')).toHaveLength(0)
    const errors = events.filter((e) => e.kind === 'error')
    expect(errors).toHaveLength(1)
    const error = errors[0]!
    if (error.kind !== 'error') throw new Error('unreachable')
    expect(error.runtimeNodeId).toBe('s')
    expect(error.detail.exceptionType).toBe('execution')
    expect(error.detail.exceptionMessage).toContain("on_absent='fail'")
  })

  it('marks the culprit node error even though no node_failed was emitted', () => {
    const errorStates = nodeEntries(events).filter(([, p]) => p.state === 'error')
    expect(errorStates.map(([id]) => id)).toEqual(['s'])
    // The node that DID run still finishes normally.
    const doneStates = nodeEntries(events).filter(([, p]) => p.state === 'done')
    expect(doneStates.map(([id]) => id)).toEqual(['m'])
  })
})

describe('routing guards', () => {

  it('FR-4 a terminal job never emits a SECOND terminal event, in any order', () => {
    // failed -> straggling run_finished: must not read as a success reversal
    const n1 = new DinksterNormalizer(CONN, () => 0)
    expect(
      n1.normalize({ type: 'job_state', jobId: 'j', state: 'failed', error: { message: 'boom' } })
        .some((e) => e.kind === 'error'),
    ).toBe(true)
    expect(n1.normalize({ type: 'run_finished', jobId: 'j' })).toEqual([])
    // Engine completion cannot hide a failed or cancelled job settlement.
    for (const state of ['failed', 'cancelled'] as const) {
      const normalizer = new DinksterNormalizer(CONN, () => 0)
      expect(normalizer.normalize({ type: 'run_finished', jobId: 'j' })).toEqual([])
      expect(normalizer.normalize({ type: 'job_state', jobId: 'j', state, error: { message: 'settlement failed' } }))
        .toEqual([expect.objectContaining({ kind: state === 'failed' ? 'error' : 'cancelled' })])
      expect(normalizer.normalize({ type: 'run_finished', jobId: 'j' })).toEqual([])
      expect(normalizer.normalize({ type: 'job_state', jobId: 'j', state: 'completed' })).toEqual([])
    }
  })

  it('never cross-routes concurrent jobs interleaved on one socket', () => {
    const normalizer = new DinksterNormalizer(CONN, () => 0)
    const out: NormalizedEvent[] = []
    const a = [...successStream.messages]
    const b = [...cachedStream.messages]
    while (a.length > 0 || b.length > 0) {
      const nextA = a.shift()
      const nextB = b.shift()
      if (nextA) out.push(...normalizer.normalize(toWire(nextA)))
      if (nextB) out.push(...normalizer.normalize(toWire(nextB)))
    }
    const keys = new Map<string, string>([
      [keyOf('job-1'), 'job-1'],
      [keyOf('job-2'), 'job-2'],
    ])
    const byJob = new Map<string, NormalizedEvent[]>()
    for (const e of out) {
      if (!isExecutionEvent(e)) continue
      const jobId = keys.get(executionKey(e.execution))
      expect(jobId).toBeDefined()
      byJob.set(jobId!, [...(byJob.get(jobId!) ?? []), e])
    }
    // job-1 owns the running/done states + preview; job-2 owns all cached.
    const job1 = byJob.get('job-1')!
    const job2 = byJob.get('job-2')!
    expect(job1.filter((e) => e.kind === 'completed')).toHaveLength(1)
    expect(job2.filter((e) => e.kind === 'completed')).toHaveLength(1)
    expect(nodeEntries(job1).some(([, p]) => p.state === 'cached')).toBe(false)
    expect(nodeEntries(job2).every(([, p]) => p.state === 'cached')).toBe(true)
    expect(job1.filter((e) => e.kind === 'preview')).toHaveLength(1)
    expect(job2.filter((e) => e.kind === 'preview')).toHaveLength(0)
  })

  it('emits per-connection queue depth from queue_state', () => {
    const normalizer = new DinksterNormalizer(CONN, () => 0)
    const events = normalizer.normalize({ type: 'queue_state', queued: 3, running: 1 })
    expect(events).toEqual([
      { kind: 'status', connection: CONN, timestamp: 0, queueRemaining: 3 },
    ])
  })
})

