describe('non-semantic node activity', () => {
  const normalize = (message: DinksterRawJson): readonly NormalizedEvent[] =>
    new DinksterNormalizer(CONN, () => 17).normalize(message)

  it('normalizes lazy_demand detail without claiming branch or execution semantics', () => {
    expect(normalize({
      type: 'node_event',
      jobId: 'job-lazy',
      runId: 'run-lazy',
      nodeId: 'switch',
      event: 'lazy_demand',
      data: {
        round: 2,
        status: 'waiting',
        requestedInputs: ['on_true', 'on_false'],
        newInputs: ['on_false'],
        demandedInputs: ['on_true', 'on_false'],
        producerNodes: ['producer-b'],
      },
    })).toEqual([{
      kind: 'activity',
      execution: { connection: CONN, prompt: asPromptId('job-lazy') },
      timestamp: 17,
      activity: {
        kind: 'lazy_demand',
        nodeId: 'switch',
        round: 2,
        status: 'waiting',
        requestedInputs: ['on_true', 'on_false'],
        newInputs: ['on_false'],
        demandedInputs: ['on_true', 'on_false'],
        producerNodes: ['producer-b'],
      },
    }])
  })

  it('normalizes cache_miss detail while omitting its cache key', () => {
    const events = normalize({
      type: 'cache_miss',
      jobId: 'job-cache',
      runId: 'run-cache',
      nodeId: 'sampler',
      detail: {
        cache_key: 'secret-opaque-key',
        reason: 'inputs-changed',
        changed_inputs: ['seed'],
        added_inputs: ['control'],
        removed_inputs: ['legacy'],
      },
    })
    expect(events).toEqual([{
      kind: 'activity',
      execution: { connection: CONN, prompt: asPromptId('job-cache') },
      timestamp: 17,
      activity: {
        kind: 'cache_miss',
        nodeId: 'sampler',
        reason: 'inputs-changed',
        changedInputs: ['seed'],
        addedInputs: ['control'],
        removedInputs: ['legacy'],
      },
    }])
    expect(JSON.stringify(events)).not.toContain('secret-opaque-key')
  })

})

describe('job failure error hints', () => {
  const failureDetail = (hints?: unknown) => {
    const normalizer = new DinksterNormalizer(CONN, () => 0)
    const events = normalizer.normalize({
      type: 'job_state',
      jobId: 'hinted-job',
      state: 'failed',
      error: {
        kind: 'execution',
        message: 'expected scalar type Half but found Float',
        traceback: 'raw line one\nraw line two',
        ...(hints !== undefined ? { hints } : {}),
      },
    })
    const event = events.find((candidate) => candidate.kind === 'error')
    if (event?.kind !== 'error') throw new Error('expected an error event')
    return event.detail
  }

  it('decodes hints with and without suggestions without client-side recapping', () => {
    const detail = failureDetail([
      {
        code: 'dtype-mismatch',
        message: 'Input dtype Float does not match required dtype Half.',
      },
      {
        code: 'tensor-shape-mismatch',
        message: 'Tensor dimensions do not match.',
        suggestion: 'Try permuting the input layout.',
      },
      { code: 'device-mismatch', message: 'Inputs are on different devices.' },
      { code: 'cuda-oom', message: 'CUDA ran out of memory.' },
    ])

    expect(detail.exceptionMessage).toBe('expected scalar type Half but found Float')
    expect(detail.traceback).toEqual(['raw line one', 'raw line two'])
    expect(detail.hints).toEqual([
      {
        code: 'dtype-mismatch',
        message: 'Input dtype Float does not match required dtype Half.',
      },
      {
        code: 'tensor-shape-mismatch',
        message: 'Tensor dimensions do not match.',
        suggestion: 'Try permuting the input layout.',
      },
      { code: 'device-mismatch', message: 'Inputs are on different devices.' },
      { code: 'cuda-oom', message: 'CUDA ran out of memory.' },
    ])
  })

})

describe('connection-level control events (schema epochs, composition)', () => {
  const n = () => new DinksterNormalizer(CONN, () => 5)

  it('maps schema_changed to a connection-scoped epoch ping', () => {
    expect(n().normalize({ type: 'schema_changed', epoch: 2 })).toEqual([
      { kind: 'schemaChanged', connection: CONN, timestamp: 5, epoch: 2 },
    ])
  })

  it('maps composition_progress, phase omitted-when-absent', () => {
    expect(n().normalize({ type: 'composition_progress', done: 2, total: 5, phase: 'packs' })).toEqual([
      { kind: 'compositionProgress', connection: CONN, timestamp: 5, done: 2, total: 5, phase: 'packs' },
    ])
    expect(n().normalize({ type: 'composition_progress', done: 2, total: 5 })).toEqual([
      { kind: 'compositionProgress', connection: CONN, timestamp: 5, done: 2, total: 5 },
    ])
    expect(n().normalize({ type: 'composition_progress', done: 2 })).toEqual([])
  })

  it('maps composition_complete, defaulting the failed list to empty', () => {
    expect(n().normalize({ type: 'composition_complete', epoch: 3 })).toEqual([
      { kind: 'compositionComplete', connection: CONN, timestamp: 5, epoch: 3, failed: [] },
    ])
    expect(n().normalize({ type: 'composition_complete', epoch: 3, failed: ['bad.pack'] })).toEqual([
      { kind: 'compositionComplete', connection: CONN, timestamp: 5, epoch: 3, failed: ['bad.pack'] },
    ])
  })

  it('maps pack_failed with its error line', () => {
    expect(n().normalize({ type: 'pack_failed', pack: 'vhs.video', error: 'boom' })).toEqual([
      { kind: 'packFailed', connection: CONN, timestamp: 5, pack: 'vhs.video', error: 'boom' },
    ])
    expect(n().normalize({ type: 'pack_failed', error: 'boom' })).toEqual([])
  })

})

describe('completed-job hydration (nodeStatesFromDinksterJob)', () => {
  it('reconstructs the success job as done, with output summaries for targets', () => {
    // Job-result descriptors cover TARGET nodes only (p, r); intermediates
    // get their summaries from the live event stream, not hydration.
    expect(nodeStatesFromDinksterJob(successStream.job)).toEqual({
      m: { state: 'done' },
      a: { state: 'done' },
      p: { state: 'done', outputs: { out: { typeId: 'INT' } } },
      r: { state: 'done', outputs: { items: { typeId: 'list<INT>', length: 3 } } },
    })
  })

  it('reconstructs cached and skipped states from the live nodeStates map', () => {
    expect(nodeStatesFromDinksterJob(cachedStream.job)).toEqual({
      m: { state: 'cached' },
      a: { state: 'cached' },
      p: { state: 'cached', outputs: { out: { typeId: 'INT' } } },
      r: { state: 'cached', outputs: { items: { typeId: 'list<INT>', length: 3 } } },
    })
    expect(nodeStatesFromDinksterJob(skipStream.job)).toEqual({
      m: { state: 'done' },
      a: { state: 'skipped' },
      b: { state: 'skipped' },
    })
  })

  it('marks the failed job culprit error even without a terminal node state', () => {
    expect(nodeStatesFromDinksterJob(failureStream.job)).toEqual({
      m: { state: 'done' },
      s: { state: 'error' },
    })
  })

})
